// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(c));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);

        uint256 prevRecipientBalance = recipient.balance;
        uint256 prevContractBalance = address(c).balance;

        vm.prank(address(this));
        c.withdrawAll(recipient);

        uint256 postContractBalance = address(c).balance;
        uint256 postRecipientBalance = recipient.balance;

        assertTrue(postContractBalance == 0 && postRecipientBalance == prevRecipientBalance + prevContractBalance);
    }
}
